-- SIMULATED pre-Phase-2 MVP schema, for migration tests only. It is a best guess at the original
-- MVP structure (Nasira's original database was not available) — not a real production schema.
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, contact_preference ENUM('email','phone','both') NOT NULL DEFAULT 'email', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE listings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL, category VARCHAR(64) NOT NULL, item_condition VARCHAR(64) NOT NULL, price_daily DECIMAL(10,2) NOT NULL, ai_suggested_description TEXT NULL, final_description TEXT NOT NULL, ai_detected_attributes JSON NULL, available_now TINYINT(1) NOT NULL DEFAULT 1, available_from DATE NULL, available_until DATE NULL, published TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_listings_published (published), INDEX idx_listings_category (category), INDEX idx_listings_slug (slug), FULLTEXT idx_listings_search (title, final_description)) ENGINE=InnoDB;
CREATE TABLE listing_images (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id INT UNSIGNED NOT NULL, file_path VARCHAR(512) NOT NULL, sort_order TINYINT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (listing_id) REFERENCES listings(id) ON DELETE CASCADE, INDEX idx_listing_images_listing (listing_id)) ENGINE=InnoDB;
CREATE TABLE rental_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id INT UNSIGNED NOT NULL, renter_id INT UNSIGNED NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, message TEXT NULL, status ENUM('pending','accepted','declined') NOT NULL DEFAULT 'pending', responded_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (listing_id) REFERENCES listings(id) ON DELETE CASCADE, FOREIGN KEY (renter_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE bookings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rental_request_id INT UNSIGNED NOT NULL UNIQUE, listing_id INT UNSIGNED NOT NULL, renter_id INT UNSIGNED NOT NULL, owner_id INT UNSIGNED NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status ENUM('accepted','cancelled') NOT NULL DEFAULT 'accepted', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (rental_request_id) REFERENCES rental_requests(id) ON DELETE CASCADE, FOREIGN KEY (listing_id) REFERENCES listings(id) ON DELETE CASCADE, FOREIGN KEY (renter_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_bookings_owner (owner_id), INDEX idx_bookings_renter (renter_id)) ENGINE=InnoDB;
